// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SupportContract) predicate.SupportContract {
	return predicate.SupportContract(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SupportContract) predicate.SupportContract {
	return predicate.SupportContract(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SupportContract) predicate.SupportContract {
	return predicate.SupportContract(sql.NotPredicates(p))
}
